import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const navItems = [
  { path: '/dashboard', label: 'Dashboard', icon: '⊞' },
  { path: '/documents', label: 'Documents', icon: '📄' },
  { path: '/upload', label: 'Upload', icon: '⬆', roles: ['Admin', 'Record Manager'] },
  { path: '/reports', label: 'Reports', icon: '📊', roles: ['Admin', 'Auditor'] },
  { path: '/audit', label: 'Audit Logs', icon: '🔍', roles: ['Admin', 'Auditor'] },
];

const roleColors = {
  'Admin': '#ef4444',
  'Record Manager': '#f59e0b',
  'Authorized User': '#10b981',
  'Auditor': '#6366f1'
};

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  if (!user) return null;

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  const filtered = navItems.filter(item => !item.roles || item.roles.includes(user.role));

  return (
    <nav style={styles.nav}>
      <div style={styles.left}>
        <div style={styles.logo}>
          <span style={styles.logoIcon}>🗂</span>
          <span style={styles.logoText}>DRMS</span>
        </div>
        <div style={styles.divider} />
        {filtered.map(item => (
          <Link key={item.path} to={item.path}
            style={{ ...styles.navLink, ...(location.pathname === item.path ? styles.activeLink : {}) }}>
            <span style={styles.navIcon}>{item.icon}</span>
            {item.label}
          </Link>
        ))}
      </div>
      <div style={styles.right}>
        <div style={styles.userBadge}>
          <div style={styles.avatar}>{user.name.charAt(0).toUpperCase()}</div>
          <div style={styles.userInfo}>
            <span style={styles.userName}>{user.name}</span>
            <span style={{ ...styles.roleTag, background: roleColors[user.role] || '#6366f1' }}>{user.role}</span>
          </div>
        </div>
        <button onClick={handleLogout} style={styles.logoutBtn}>
          <span>⏻</span> Logout
        </button>
      </div>
    </nav>
  );
}

const styles = {
  nav: {
    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
    padding: '0 24px', background: 'rgba(15,23,42,0.85)', height: '64px',
    boxShadow: '0 1px 3px rgba(0,0,0,0.3)',
    position: 'sticky', top: 0, zIndex: 100,
    backdropFilter: 'blur(16px)',
    borderBottom: '1px solid rgba(255,255,255,0.08)'
  },
  left: { display: 'flex', alignItems: 'center', gap: '4px', height: '100%' },
  logo: { display: 'flex', alignItems: 'center', gap: '8px', marginRight: '8px' },
  logoIcon: { fontSize: '22px' },
  logoText: { fontSize: '18px', fontWeight: '700', color: '#818cf8', letterSpacing: '-0.5px' },
  divider: { width: '1px', height: '28px', background: 'rgba(255,255,255,0.15)', margin: '0 12px' },
  navLink: {
    display: 'flex', alignItems: 'center', gap: '6px', padding: '0 14px',
    height: '64px', color: '#94a3b8', fontSize: '14px', fontWeight: '500',
    textDecoration: 'none', borderBottom: '2px solid transparent', transition: 'all 0.2s'
  },
  activeLink: { color: '#818cf8', borderBottom: '2px solid #818cf8', background: 'rgba(129,140,248,0.08)' },
  navIcon: { fontSize: '15px' },
  right: { display: 'flex', alignItems: 'center', gap: '16px' },
  userBadge: { display: 'flex', alignItems: 'center', gap: '10px' },
  avatar: {
    width: '36px', height: '36px', borderRadius: '50%', background: 'linear-gradient(135deg, #4f46e5, #7c3aed)',
    color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontWeight: '600', fontSize: '15px'
  },
  userInfo: { display: 'flex', flexDirection: 'column', gap: '2px' },
  userName: { fontSize: '13px', fontWeight: '600', color: '#e2e8f0' },
  roleTag: { fontSize: '10px', color: '#fff', padding: '1px 7px', borderRadius: '10px', fontWeight: '600', textAlign: 'center' },
  logoutBtn: {
    display: 'flex', alignItems: 'center', gap: '6px', padding: '8px 16px',
    background: 'rgba(239,68,68,0.15)', color: '#f87171', border: '1px solid rgba(239,68,68,0.3)',
    borderRadius: '8px', cursor: 'pointer', fontSize: '13px', fontWeight: '500'
  }
};
